```js
// bounceBricks(state): resolves ball-vs-bricks collisions, discrete first, swept second.
export function bounceBricks(state) {
  const { ball } = state;
  const live = state.bricks.filter((b) => b.alive);
  if (live.length === 0) return;

  // 1. Discrete: the ball currently overlaps one or more live bricks.
  const hit = live.filter((b) => collides(ball, b));
  if (hit.length > 0) {
    // score & kill
    for (const brick of hit) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
    resolveAgainst(ball, unionOf(hit));
    return;
  }

  // 2. Swept: the ball crossed a brick between its previous and current position.
  if (ball.prevX === undefined || ball.prevY === undefined) return;
  const dx = ball.x - ball.prevX;
  const dy = ball.y - ball.prevY;
  if (dx === 0 && dy === 0) return;

  let best = null; // { brick, t, face }
  for (const brick of live) {
    const sweep = sweptHit(ball, ball.prevX, ball.prevY, brick);
    if (sweep && (best === null || sweep.t < best.t)) best = { brick, ...sweep };
  }
  if (best === null) return;

  best.brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(best.brick, state.combo);

  // position at the entry point, then push out along the face normal
  const t = best.t;
  ball.x = ball.prevX + dx * t;
  ball.y = ball.prevY + dy * t;
  // face: 'left' | 'right' | 'top' | 'bottom' | 'corner'
  resolveFace(ball, best.face);
}
```

