```js
function resolveAgainst(ball, box) {
  // penetration on each axis
  const penLeft = ball.x + ball.r - box.x;       // > 0 if ball right edge past box left
  const penRight = box.x + box.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - box.y;
  const penBottom = box.y + box.h - (ball.y - ball.r);
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    // horizontal face
    if (penLeft < penRight) { ball.vx = -Math.abs(ball.vx); ball.x = box.x - ball.r; }
    else { ball.vx = Math.abs(ball.vx); ball.x = box.x + box.w + ball.r; }
  } else if (penY < penX) {
    if (penTop < penBottom) { ball.vy = -Math.abs(ball.vy); ball.y = box.y - ball.r; }
    else { ball.vy = Math.abs(ball.vy); ball.y = box.y + box.h + ball.r; }
  } else {
    // corner: both flip; push out to the corner (both axes at the tie)
    if (penLeft <= penRight) ball.vx = -Math.abs(ball.vx); else ball.vx = Math.abs(ball.vx);
    if (penTop <= penBottom) ball.vy = -Math.abs(ball.vy); else ball.vy = Math.abs(ball.vy);
    ball.x = penLeft <= penRight ? box.x - ball.r : box.x + box.w + ball.r;
    ball.y = penTop <= penBottom ? box.y - ball.r : box.y + box.h + ball.r;
  }
}
```

