```js
function sweptHit(ball, prevX, prevY, brick) {
  const x0 = prevX, y0 = prevY, x1 = ball.x, y1 = ball.y;
  const dx = x1 - x0, dy = y1 - y0;
  // expanded box
  const boxL = brick.x - ball.r, boxR = brick.x + brick.w + ball.r;
  const boxT = brick.y - ball.r, boxB = brick.y + brick.h + ball.r;

  let tmin = 0, tmax = 1;
  let face = null;
  // x slab
  if (dx === 0) {
    if (x0 < boxL || x0 > boxR) return null;
  } else {
    let t1 = (boxL - x0) / dx, t2 = (boxR - x0) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; face = dx > 0 ? 'left' : 'right'; }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }
  // y slab
  if (dy === 0) {
    if (y0 < boxT || y0 > boxB) return null;
  } else {
    let t1 = (boxT - y0) / dy, t2 = (boxB - y0) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; face = dy > 0 ? 'top' : 'bottom'; }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }
  if (tmin < 1) return { t: tmin, face: face === null ? 'corner' : face };
  return null;
}
```

