Algorithm for bounceBricks:

```js
export function bounceBricks(state) {
  const { ball, bricks } = state;
  const prevX = ball.prevX, prevY = ball.prevY;
  const live = bricks.filter((b) => b.alive);

  // 1. Discrete: ball embedded in a cluster of bricks.
  const overlapped = live.filter((b) => collides(ball, b));
  if (overlapped.length > 0) {
    // kill & score every overlapped brick
    for (const b of overlapped) {
      b.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(b, state.combo);
    }
    // union AABB
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const b of overlapped) {
      minX = Math.min(minX, b.x); maxX = Math.max(maxX, b.x + b.w);
      minY = Math.min(minY, b.y); maxY = Math.max(maxY, b.y + b.h);
    }
    resolveAgainstRect(state, minX, minY, maxX, maxY, ball, true);
    return;
  }

  // 2. Swept: crossed a brick between prev and current position.
  if (prevX !== undefined && (prevX !== ball.x || prevY !== ball.y)) {
    const hit = sweptHit(ball, prevX, prevY, live);
    if (hit) {
      hit.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(hit.brick, state.combo);
      ball.x = hit.x; ball.y = hit.y;
      applyBounce(ball, hit.axis);  // axis: 'x' | 'y' | 'both'
    }
  }
}
```

