function sweptHit(ball, x0, y0, bricks) {
  const x1 = ball.x, y1 = ball.y;
  const dx = x1 - x0, dy = y1 - y0;
  let best = null;
  for (const brick of bricks) {
    // expanded box
    const xa = brick.x - ball.r, xb = brick.x + brick.w + ball.r;
    const ya = brick.y - ball.r, yb = brick.y + brick.h + ball.r;
    let tmin = 0, tmax = 1, axis = null;
    if (Math.abs(dx) < 1e-12) {
      if (x0 < xa || x0 > xb) continue;
    } else {
      let t1 = (xa - x0) / dx, t2 = (xb - x0) / dx;
      let lo = Math.min(t1, t2), hi = Math.max(t1, t2);
      if (lo > tmin) { tmin = lo; axis = 'x'; }
      tmax = Math.min(tmax, hi);
      if (tmin > tmax) continue;
    }
    if (Math.abs(dy) < 1e-12) {
      if (y0 < ya || y0 > yb) continue;
    } else {
      let t1 = (ya - y0) / dy, t2 = (yb - y0) / dy;
      let lo = Math.min(t1, t2), hi = Math.max(t1, t2);
      if (lo > tmin) { tmin = lo; axis = 'y'; }
      tmax = Math.min(tmax, hi);
      if (tmin > tmax) continue;
    }
    if (!best || tmin < best.t) {
      best = { brick, t: tmin, axis };
    }
  }
  if (!best || best.t > 1) return null;
  return {
    brick: best.brick,
    x: x0 + dx * best.t,
    y: y0 + dy * best.t,
    axis: best.axis,  // 'x' | 'y' | 'both' (corner tie)
  };
}
```

