// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// A canvas context that swallows every draw call (the collision path in
// frame() only reads the ball and the bricks).
function fakeCtx() {
  const nothing = () => {};
  return new Proxy(
    {},
    {
      get: (_, name) => (name === 'canvas' ? { width: WIDTH, height: HEIGHT } : nothing),
      set: () => true,
    },
  );
}

// --- Paddle: the ball must always come back out through the top -----------

// A fast ball crosses more than the paddle's 12 px band in a single capped
// step (level 2: 350 px/s * 0.05 s = 17.5 px): the discrete test would miss it.
// The bounce must trigger on the swept crossing of the paddle's top plane.
test('paddle: une balle rapide ne traverse pas le paddle', () => {
  const state = createState(2);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(2) };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, `vy devait devenir négatif : ${state.ball.vy}`);
});

// The old test only checks the ball's CENTER against the paddle's x-range: a
// ball clipping the paddle's corner (center just outside) never bounces. Any
// span overlap with the paddle's top face must count.
test('paddle: un contact au coin du paddle compte', () => {
  const state = createState(1);
  state.paddle.x = 320; // paddle 320..416
  state.ball = { x: 318, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: -200, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, `vy devait devenir négatif : ${state.ball.vy}`);
});

// The mouse teleports the paddle between two frames (mousemove handler): the
// paddle can jump over the falling ball. The x test must cover the union of
// the previous and the current paddle position.
test('paddle: un paddle téléporté sur la balle la renvoie vers le haut', () => {
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  state.paddle.x = 20; // first step: paddle far away, no bounce
  step(state, 1 / 60);
  state.paddle.x = 560; // teleport (mousemove between two frames)
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, `vy devait devenir négatif : ${state.ball.vy}`);
});

// --- Speed: a paddle bounce keeps the level's speed ------------------------

// The old code rewrites vx = speed * 0.6 * hit and keeps vy untouched: at the
// paddle edge (hit = 1) the norm becomes speed * sqrt(1.36) ~ 1.166 * speed.
// The bounce speed must stay the level's speed.
test('paddle: la norme de la vitesse reste celle du niveau', () => {
  const state = createState(1);
  const speed = ballSpeed(1);
  state.paddle.x = 100; // paddle 100..196, hit = 1 at the right edge
  state.ball = { x: 196, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: speed };
  step(state, 1 / 60);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - speed) < 1e-6, `norme ${norm} != ${speed}`);
});

// --- Dead angle: a center hit must stay playable ---------------------------

// A contact at the exact center of the paddle gives hit = 0, hence vx = 0 and
// a ball looping straight up and down forever. The outgoing vx needs a floor.
test('paddle: un contact au centre garde une trajectoire jouable', () => {
  const state = createState(1);
  const speed = ballSpeed(1);
  state.paddle.x = 100; // paddle center at 148
  state.ball = { x: 148, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: speed };
  step(state, 1 / 60);
  assert.ok(
    Math.abs(state.ball.vx) >= 0.15 * speed,
    `vx devait rester jouable : ${state.ball.vx}`,
  );
});

// --- dt-independence -------------------------------------------------------

// The same fast pass at 60 fps (dt = 1/60) and at the capped step (dt = 0.05)
// must give the same result: at level 6 one step is 35.5 px, more than the
// 34 px (brick height + ball diameter) to cross, so the discrete check misses
// the brick entirely at 0.05 while hitting it at 1/60. The swept segment
// between the two positions makes the outcome dt-independent.
test('dt: même passage, même rebond à 60 fps et à 20 fps', () => {
  for (const dt of [1 / 60, 0.05]) {
    const state = createState(6);
    const brick = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 };
    state.bricks = [brick];
    state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
    frame(fakeCtx(), state);
    step(state, dt);
    frame(fakeCtx(), state);
    assert.ok(!brick.alive, `dt=${dt} : la brique doit être touchée`);
    assert.ok(state.ball.vy > 0, `dt=${dt} : la balle doit repartir vers le bas : ${state.ball.vy}`);
  }
});

