// --- Brick collision (pure logic, no DOM) -----------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) { ... }

// Resolves a collision against an axis-aligned rectangle: picks the face by
// smallest penetration (a tie means a corner: both axes flip), pushes the
// ball out to the exact face, and flips the matching velocity components.
function resolveAgainstRect(state, rx, ry, rw, rh) {
  const { ball } = state;
  const penLeft = ball.x + ball.r - rx;
  const penRight = rx + rw - (ball.x - ball.r);
  const penTop = ball.y + ball.r - ry;
  const penBottom = ry + rh - (ball.y - ball.r);
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);
  if (penX <= 0 || penY <= 0) return;

  const TIE = 1e-9;
  if (Math.abs(penX - penY) <= TIE) {
    // Corner: both faces were hit with equal penetration.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = penLeft <= penRight ? rx - ball.r : rx + rw + ball.r;
    ball.y = penTop <= penBottom ? ry - ball.r : ry + rh + ball.r;
    return;
  }
  if (penX < penY) {
    ball.vx = -ball.vx;
    ball.x = penLeft <= penRight ? rx - ball.r : rx + rw + ball.r;
  } else {
    ball.vy = -ball.vy;
    ball.y = penTop <= penBottom ? ry - ball.r : ry + rh + ball.r;
  }
}

// Scores and kills a brick, exactly as frame() used to.
function breakBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Brick collision for one pass: kills every overlapping brick (once), then
// resolves the ball against the union of their rectangles so a grid seam is a
// single bounce. Called by frame() after step() has moved the ball; ball.prevX
// / prevY (recorded by step) extend the test to the swept segment of the move.
export function bounceBricks(state) {
  const { ball, bricks } = state;

  // 1. Discrete: the ball overlaps a cluster of bricks right now.
  const hit = bricks.filter((b) => b.alive && collides(ball, b));
  if (hit.length > 0) {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const brick of hit) {
      breakBrick(state, brick);
      minX = Math.min(minX, brick.x);
      minY = Math.min(minY, brick.y);
      maxX = Math.max(maxX, brick.x + brick.w);
      maxY = Math.max(maxY, brick.y + brick.h);
    }
    resolveAgainstRect(state, minX, minY, maxX - minX, maxY - minY);
    return;
  }

  // 2. Swept: ... (step B)
