}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision resolution (pure logic, no DOM) ------------------------

// Scores and kills a brick, exactly as frame() used to do inline.
function breakBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Resolves a collision against an axis-aligned rectangle: the hit axis is the
// one of the SMALLEST penetration (a tie means a corner: both components
// flip), and the ball is pushed back out to the exact face so the next frame
// does not re-detect the overlap and re-invert the velocity.
function resolveAgainstRect(state, rx, ry, rw, rh) {
  const { ball } = state;
  const penLeft = ball.x + ball.r - rx;
  const penRight = rx + rw - (ball.x - ball.r);
  const penTop = ball.y + ball.r - ry;
  const penBottom = ry + rh - (ball.y - ball.r);
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);
  if (penX <= 0 || penY <= 0) return; // touching but not overlapping

  const TIE = 1e-9;
  if (Math.abs(penX - penY) <= TIE) {
    // Corner: both faces hit with equal penetration, both components flip.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = penLeft <= penRight ? rx - ball.r : rx + rw + ball.r;
    ball.y = penTop <= penBottom ? ry - ball.r : ry + rh + ball.r;
    return;
  }
  if (penX < penY) {
    ball.vx = -ball.vx;
    ball.x = penLeft <= penRight ? rx - ball.r : rx + rw + ball.r;
  } else {
    ball.vy = -ball.vy;
    ball.y = penTop <= penBottom ? ry - ball.r : ry + rh + ball.r;
  }
}

// Earliest swept hit of the ball's move segment against the expanded box of
// each live brick (slab method). Returns the brick, the entry point and the
// face entered ('left' | 'right' | 'top' | 'bottom' | 'corner'), or null.
function sweptHit(ball, x0, y0, bricks) {
  const x1 = ball.x;
  const y1 = ball.y;
  const dx = x1 - x0;
  const dy = y1 - y0;
  let bestT = Infinity;
  let best = null;
  for (const brick of bricks) {
    const xa = brick.x - ball.r;
    const xb = brick.x + brick.w + ball.r;
    const ya = brick.y - ball.r;
    const yb = brick.y + brick.h + ball.r;

    let txIn = -Infinity;
    let txOut = Infinity;
    if (Math.abs(dx) < 1e-12) {
      if (x0 < xa || x0 > xb) continue; // parallel, no crossing
    } else {
      txIn = Math.min((xa - x0) / dx, (xb - x0) / dx);
      txOut = Math.max((xa - x0) / dx, (xb - x0) / dx);
    }
    let tyIn = -Infinity;
    let tyOut = Infinity;
    if (Math.abs(dy) < 1e-12) {
      if (y0 < ya || y0 > yb) continue; // parallel, no crossing
    } else {
      tyIn = Math.min((ya - y0) / dy, (yb - y0) / dy);
      tyOut = Math.max((ya - y0) / dy, (yb - y0) / dy);
    }
    const tIn = Math.max(0, txIn, tyIn);
    const tOut = Math.min(1, txOut, tyOut);
    if (tIn > tOut) continue;
    if (tIn >= bestT) continue;

    // The face is the slab whose entry is the latest (the first plane hit).
    let face;
    if (txIn > tyIn + 1e-9) face = dx > 0 ? 'left' : 'right';
    else if (tyIn > txIn + 1e-9) face = dy > 0 ? 'top' : 'bottom';
    else face = 'corner';
    bestT = tIn;
    best = { brick, x: x0 + dx * tIn, y: y0 + dy * tIn, face };
  }
  return best;
}

// Brick collision for one pass. Kills every overlapping brick, then resolves
// the ball ONCE against the union of their rectangles, so a grid seam (gap
// 8 px < ball diameter 14 px) is a single bounce and not two cancelled ones.
// If the ball no longer overlaps but its move segment crossed a brick between
// the previous and the current position, the swept hit is resolved instead:
// this is what stops a fast ball from tunneling through a brick (#1).
export function bounceBricks(state) {
  const { ball, bricks } = state;

  // 1. Discrete: the ball overlaps a cluster of bricks right now.
  const hit = bricks.filter((b) => b.alive && collides(ball, b));
  if (hit.length > 0) {
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const brick of hit) {
      breakBrick(state, brick);
      minX = Math.min(minX, brick.x);
      minY = Math.min(minY, brick.y);
      maxX = Math.max(maxX, brick.x + brick.w);
      maxY = Math.max(maxY, brick.y + brick.h);
    }
    resolveAgainstRect(state, minX, minY, maxX - minX, maxY - minY);
    return;
  }

  // 2. Swept: the move crossed a brick between the two positions.
  const prevX = ball.prevX;
  const prevY = ball.prevY;
  if (prevX === undefined || (prevX === ball.x && prevY === ball.y)) return;
  const crossed = sweptHit(ball, prevX, prevY, bricks.filter((b) => b.alive));
  if (!crossed) return;

  breakBrick(state, crossed.brick);
  ball.x = crossed.x;
  ball.y = crossed.y;
  const brick = crossed.brick;
  if (crossed.face === 'left') {
    ball.vx = -ball.vx;
    ball.x = brick.x - ball.r;
  } else if (crossed.face === 'right') {
    ball.vx = -ball.vx;
    ball.x = brick.x + brick.w + ball.r;
  } else if (crossed.face === 'top') {
    ball.vy = -ball.vy;
    ball.y = brick.y - ball.r;
  } else if (crossed.face === 'bottom') {
    ball.vy = -ball.vy;
    ball.y = brick.y + brick.h + ball.r;
  } else {
    // corner: both components flip, ball left at the entry point
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

