// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Record where the move starts: frame()'s brick pass sweeps the segment
  // between this position and the new one (tunneling, #1).
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: the ball always comes back out through the TOP face. The old
  // discrete test (bottom edge landing inside the paddle's 12 px band, center
  // inside its x-range) let a fast ball tunnel through on a long step, missed
  // corner contacts, and ignored a paddle teleported by the mouse. Instead:
  // bounce when the bottom edge crosses the paddle's top plane during this
  // step, or when a teleporting paddle catches the ball inside its band; the
  // x-range is the paddle's swept span (previous + current position).
  const p0x = paddle.prevX ?? paddle.x;
  const b0 = ball.prevY + ball.r;
  const b1 = ball.y + ball.r;
  const overPaddle =
    ball.x + ball.r >= Math.min(p0x, paddle.x) &&
    ball.x - ball.r <= Math.max(p0x + paddle.w, paddle.x + paddle.w);
  const crossesTop = b0 <= paddle.y && b1 >= paddle.y;
  const caughtInside = b1 >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h;
  if (ball.vy > 0 && overPaddle && (crossesTop || caughtInside)) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit, but the outgoing
    // speed is always the level's speed (renormalized), and never a dead
    // vertical (|vx| floored): a center hit must stay playable.
    const speed = ballSpeed(state.level);
    const hit = Math.max(-1, Math.min(1, (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2)));
    ball.vx = speed * 0.6 * hit;
    if (Math.abs(ball.vx) < speed * 0.2) {
      ball.vx = (ball.vx < 0 ? -1 : 1) * speed * 0.2;
    }
    const norm = Math.hypot(ball.vx, ball.vy);
    ball.vx = (ball.vx / norm) * speed;
    ball.vy = (ball.vy / norm) * speed;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  // (the paddle's previous position is recorded so the next step can test
  // the paddle's swept x-range against a teleporting mouse).
  paddle.prevX = paddle.x;
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

